import { createPrivateKey, createPublicKey, sign, type KeyObject } from 'node:crypto';
import { readFileSync } from 'node:fs';
import type { Page } from '@playwright/test';

/**
 * TEST-ONLY wallet for the smoke (F7): it registers itself through the Wallet Standard before the app loads, exactly
 * like Phantom or Solflare, and signs with the key pair generated by SmokeWalletTool. The key stays in this Node
 * process (the file lives outside the repository and is deleted by scripts/verify.sh); the page only receives the
 * public key and the signatures.
 */
export interface SmokeWallet {
  address: string;
  key: KeyObject;
  publicKey: number[];
}

const PKCS8_ED25519_PREFIX = '302e020100300506032b657004220420';

export function loadSmokeWallet(file = process.env.SMOKE_WALLET_FILE): SmokeWallet {
  if (!file) {
    throw new Error('SMOKE_WALLET_FILE is not set (scripts/verify.sh sets it)');
  }
  const { address, seed } = JSON.parse(readFileSync(file, 'utf8')) as {
    address: string;
    seed: string;
  };
  const der = Buffer.concat([
    Buffer.from(PKCS8_ED25519_PREFIX, 'hex'),
    Buffer.from(seed, 'base64'),
  ]);
  const key = createPrivateKey({ key: der, format: 'der', type: 'pkcs8' });
  const spki = createPublicKey(key).export({ format: 'der', type: 'spki' });
  return { address, key, publicKey: Array.from(spki.subarray(spki.length - 32)) };
}

export function signWith(wallet: SmokeWallet, message: string): Buffer {
  return sign(null, Buffer.from(message, 'utf8'), wallet.key);
}

export async function installTestWallet(page: Page, wallet: SmokeWallet): Promise<void> {
  await page.exposeFunction('__memetradeSmokeSign', (messageBase64: string) =>
    sign(null, Buffer.from(messageBase64, 'base64'), wallet.key).toString('base64'),
  );
  await page.addInitScript(
    ({ address, publicKey }) => {
      type Api = { register: (wallet: unknown) => void };
      const account = {
        address,
        publicKey: new Uint8Array(publicKey),
        chains: ['solana:mainnet'],
        features: ['solana:signMessage'],
      };
      const toBase64 = (bytes: Uint8Array) => btoa(String.fromCharCode(...bytes));
      const fromBase64 = (text: string) => Uint8Array.from(atob(text), (c) => c.charCodeAt(0));
      const signer = (window as unknown as { __memetradeSmokeSign: (m: string) => Promise<string> })
        .__memetradeSmokeSign;
      const wallet = {
        version: '1.0.0',
        name: 'Phantom',
        icon: 'data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciLz4=',
        chains: ['solana:mainnet'],
        accounts: [account],
        features: {
          'standard:connect': { version: '1.0.0', connect: async () => ({ accounts: [account] }) },
          'standard:events': { version: '1.0.0', on: () => () => undefined },
          'solana:signMessage': {
            version: '1.0.0',
            signMessage: async (...inputs: Array<{ message: Uint8Array }>) =>
              Promise.all(
                inputs.map(async (input) => ({
                  signedMessage: input.message,
                  signature: fromBase64(await signer(toBase64(input.message))),
                })),
              ),
          },
        },
      };
      const callback = (api: Api) => api.register(wallet);
      window.addEventListener('wallet-standard:app-ready', (event) =>
        callback((event as CustomEvent<Api>).detail),
      );
      window.dispatchEvent(
        new CustomEvent('wallet-standard:register-wallet', { detail: callback }),
      );
    },
    { address: wallet.address, publicKey: wallet.publicKey },
  );
}

/** Signs in through the app UI with the test wallet and waits for the scanner list. */
export async function signInThroughTheApp(page: Page, wallet: SmokeWallet): Promise<void> {
  await installTestWallet(page, wallet);
  await page.goto('/entrar?origem=/scanner');
  await page.getByTestId('login-connect-phantom').click();
  await page.waitForURL((url) => url.pathname === '/scanner');
}
